import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"SePay Payment ACID Verification Suite, Java Benchmark Runner & Subscription Production Observability","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/07-billing-publisher-and-observability/payment-java-runner/spec.md","filePath":"feature/modules/07-billing-publisher-and-observability/payment-java-runner/spec.md"}'),n={name:"feature/modules/07-billing-publisher-and-observability/payment-java-runner/spec.md"};function r(s,e,c,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="sepay-payment-acid-verification-suite-java-benchmark-runner-subscription-production-observability" tabindex="-1">SePay Payment ACID Verification Suite, Java Benchmark Runner &amp; Subscription Production Observability <a class="header-anchor" href="#sepay-payment-acid-verification-suite-java-benchmark-runner-subscription-production-observability" aria-label="Permalink to &quot;SePay Payment ACID Verification Suite, Java Benchmark Runner &amp; Subscription Production Observability&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>payment-java-runner</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>07-billing-publisher-and-observability</code> — Billing Verification, Publisher Resilience &amp; System Health Observability</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>payment-java-runner</code>, <code>payment-tests-in-repository</code>, <code>subscription-production-observability</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/08-subscription-billing/3-9-1-upgrade-plan/spec.html">FR 3.9.1 — Upgrade Plan</a> · <a href="./../../../srs/08-subscription-billing/3-9-2-make-payment-sepay/spec.html">FR 3.9.2 — Make Payment (SePay)</a> · <a href="./../../../srs/09-admin-functions/3-10-3-system-health-monitoring/spec.html">FR 3.10.3 — System Health Monitoring</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Consolidate BrandHub&#39;s financial reliability and operational reconciliation stack: the deterministic <strong>Java Payment API, ACID Concurrency &amp; Apache Bench Load Runner</strong> (<code>payment-java-runner</code>), the <strong>In-Repository Business Service Payment &amp; Webhook Regression Suite</strong> (<code>payment-tests-in-repository</code>), and <strong>Subscription Production Observability &amp; Admin Reconciliation</strong> (<code>SubscriptionOperationsController</code> — <code>subscription-production-observability</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Admin</code> or platform engineer, I want automated ACID concurrency tests (<code>payment-tests-in-repository</code>), reproducible Java load/chaos verification (<code>payment-java-runner</code>), and live operational issue detection &amp; reconciliation (<code>GET /api/v1/admin/billing/operations/issues|status</code> &amp; <code>POST /reconcile</code>) so zero SePay webhook anomalies or outbox stalls go unnoticed.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Java Payment API / ACID / Load Runner (<code>payment-java-runner</code>):</strong> Standalone Java HTTP + JDBC verification harness executing sequential contract checks, concurrent SePay webhook replay storms, race-timed <code>EXPIRED</code> vs <code>PENDING_PAYMENT</code> fulfillment tests, double-payment <code>MANUAL_REVIEW</code> guards (<code>AB-10</code>), and Apache Bench throughput baselines against isolated PostgreSQL instances without touching live bank accounts.</li><li><strong>In-Repository Business Payment Suite (<code>payment-tests-in-repository</code>):</strong> JUnit 5 + Testcontainers PostgreSQL transaction-proxy tests inside <code>brandhub-business-service</code> verifying <code>AgencyBillingService</code>, <code>(provider, merchant_account, event_key)</code> uniqueness, lock ordering (<code>Agency -&gt; Order</code>), rollback atomicity across <code>billing_orders</code> / <code>billing_payments</code> / <code>credit_grants</code> / <code>billing_outbox_events</code>, and exact <code>BIGINT</code> ledger invariants.</li><li><strong>Subscription Production Observability (<code>subscription-production-observability</code>):</strong> <code>SubscriptionOperationsController</code> (<code>GET /api/v1/admin/billing/operations/issues</code>, <code>GET /status</code>, <code>POST /reconcile</code>) backed by PostgreSQL <code>subscription_operational_issues</code>, <code>subscription_observation_jobs</code>, and <code>subscription_provider_checks</code> surfaces unmatched transfers, delayed outbox events, or manual-review orders to <code>Admin</code> with audited reconciliation actions.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>admin.billingOps.{issues,status,reconcile,manualReview}.*</code> in <code>src/i18n/locales/{vi,en}/admin.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/admin/components/AdminRevenuePanel.tsx</code> &amp; <code>AdminInvoicesPanel.tsx</code> (manual-review status &amp; audit badges)</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/admin/AdminInvoicesScreen.tsx</code> (read-only operational status badges)</li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/admin/billing/operations/issues</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>SubscriptionOperationsController</code> -&gt; lists open <code>subscription_operational_issues</code> (<code>MANUAL_REVIEW</code>, unmatched webhooks, outbox lag)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/admin/billing/operations/status</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>SubscriptionOperationsController</code> -&gt; health of <code>subscription_observation_jobs</code> &amp; <code>subscription_provider_checks</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/admin/billing/operations/reconcile</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>SubscriptionOperationsController</code> -&gt; audited operator reconciliation &amp; issue resolution</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Uncertain Commit / Network Drop on Webhook:</strong> Provider replay is idempotent; reconciliation never double-grants entitlements (<code>billing_order_fulfillments</code> unique constraint).</li><li><strong>Test Harness Safety Guard:</strong> <code>payment-java-runner</code> refuses non-local / non-fixture JDBC URLs so load tests can never target production databases.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/08-subscription-billing/3-9-1-upgrade-plan/spec.html">FR 3.9.1 — Upgrade Plan</a> · <a href="./../../../srs/08-subscription-billing/3-9-2-make-payment-sepay/spec.html">FR 3.9.2 — Make Payment (SePay)</a> · <a href="./../../../srs/09-admin-functions/3-10-3-system-health-monitoring/spec.html">FR 3.10.3 — System Health Monitoring</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/08-subscription-billing.html">BA 08 Subscription &amp; Billing</a> · <a href="./../../../../ba/09-admin-functions.html">BA 09 Admin Functions</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const b=t(n,[["render",r]]);export{g as __pageData,b as default};
